<div class="detail-breadcrumb"><a href="/properties">The collection</a> / <?= e($p['city']) ?> / <?= e($p['title']) ?></div><section class="detail-gallery"><img class="main-image" src="<?= e($p['cover_url'] ?: '/assets/favicon.svg') ?>" alt="Illustrative photograph of <?= e($p['title']) ?>"><div><?php foreach (array_slice(array_filter($data['media'],fn($m)=>$m['kind']==='photo'),1,2) as $m): ?><img src="<?= e(mediaUrl($m)) ?>" alt="Illustrative property interior"><?php endforeach ?></div></section><div class="detail-layout"><div class="detail-copy"><span class="eyebrow">DEMONSTRATION <?= e(strtoupper($p['property_type'])) ?> · <?= $p['purpose']==='sale'?'FOR SALE':'FOR RENT' ?></span><div class="detail-top"><div><h1><?= e($p['title']) ?></h1><p class="location"><?= icon('pin') ?><?= e($p['city']) ?> · <?= e($p['address']) ?></p></div><div class="detail-price"><?= money($p['price_minor']) ?><?= $p['purpose']==='rent'?'<small>per month</small>':'' ?><small><?= e(strtoupper(str_replace('_',' ',$p['status']))) ?></small></div></div><div class="detail-specs"><span><?= icon('bed') ?><?= $p['bedrooms'] ?> bedrooms</span><span><?= icon('bath') ?><?= (float)$p['bathrooms'] ?> bathrooms</span><span><?= icon('area') ?><?= number_format((float)$p['floor_area']) ?> <?= e($p['area_unit']) ?></span></div><h3>A place to make your own.</h3><p><?= nl2br(e($p['description'])) ?></p><div class="notice">Fictional demonstration listing. Photography is illustrative. Prices do not represent an offer or verified market valuation.</div><h3>The details</h3><div class="check-list"><?php foreach ($data['amenities'] as $a): ?><span><?= icon('check') ?> <?= e($a['name']) ?></span><?php endforeach ?></div><?php if ($data['availability']): ?><h3>Viewing availability</h3><?php foreach ($data['availability'] as $v): ?><p class="tiny"><?= $v['open_house']?'Open house':'Available' ?>: <?= e($v['starts_at']) ?> – <?= e($v['ends_at']) ?> UTC</p><?php endforeach; endif ?><h3>Location, with privacy in mind.</h3><p><?= e($p['city']) ?> · <?= e(ucfirst($p['location_privacy'])) ?> location disclosure</p><p class="tiny"><?= $p['location_privacy']==='private'?'Map location withheld.':('Coordinates: '.e($p['latitude']).', '.e($p['longitude']).'. Approximate locations are rounded; no map provider is connected.') ?></p><h3>Price history</h3><div class="history"><?php foreach ($data['prices'] as $r): ?><div><?= e($r['created_at']) ?> UTC · <?= money($r['price_minor']) ?></div><?php endforeach ?></div><?php foreach ($data['media'] as $m): ?><?php if ($m['kind']==='floorplan'): ?><p><a class="text-link" href="<?= e(mediaUrl($m)) ?>">View floor plan <?= icon('arrow') ?></a></p><?php endif ?><?php endforeach ?><?php if($p['video_url'] || $p['tour_url']): ?><h3>Another perspective</h3><div class="record-links"><?php foreach(['video_url'=>'Watch property video','tour_url'=>'Explore virtual tour'] as $key=>$label): if($p[$key]): ?><a href="<?= e($p[$key]) ?>" target="_blank" rel="noopener noreferrer"><?= e($label) ?> ?</a><?php endif; endforeach ?></div><?php endif ?><h3>A nonbinding proposal</h3><p>Record proposed terms for the seller to review. Acceptance records agreement in principle and does not transfer ownership.</p><?php if ($user): ?><form class="panel" action="/proposal" method="post"><?= csrf() ?><input type="hidden" name="listing_id" value="<?= $p['id'] ?>"><div class="form-grid"><label class="field"><span>Proposed amount (USD)</span><input type="number" name="amount" min="1" step=".01" required></label><label class="field wide"><span>Terms and conditions</span><textarea name="terms" minlength="5" required placeholder="Financing, timing, inspection conditions…"></textarea></label></div><button class="button">Submit proposal <?= icon('arrow') ?></button></form><?php else: ?><a class="button" href="/login">Sign in to submit a proposal</a><?php endif ?></div><aside class="detail-sidebar"><div class="panel"><?php if ($data['agent']): $a=$data['agent']; ?><a class="agent-card" href="/agent?id=<?= $a['user_id'] ?>"><img src="<?= e($a['photo'] ?: '/assets/favicon.svg') ?>" alt="Illustrative agent portrait"><div><span class="eyebrow">YOUR PROPERTY CONTACT</span><h3><?= e($a['name']) ?></h3><p>Demonstration agent</p><?php if ($a['verified_at']): ?><span class="verified">Admin verified · demo profile</span><?php endif ?></div></a><?php endif ?><form action="/conversation" method="post"><?= csrf() ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="button">Message the agent <?= icon('arrow') ?></button></form><form action="/favorite" method="post"><?= csrf() ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="button outline"><?= icon('heart') ?> Save this home</button></form><hr><h3>Come and take a look.</h3><form action="/viewing" method="post"><?= csrf() ?><input type="hidden" name="listing_id" value="<?= $p['id'] ?>"><label class="field"><span>Preferred date & time</span><input type="datetime-local" name="starts_at" required></label><label class="field"><span>Your time zone</span><input name="timezone" data-timezone value="<?= e($user['timezone'] ?? 'UTC') ?>" required></label><label class="field"><span>A note for your agent</span><textarea name="note" placeholder="Anything we should know?"></textarea></label><button class="button">Request a viewing <?= icon('arrow') ?></button><p class="tiny">One-hour appointment. Subject to confirmation. Conflicting times cannot be booked.</p></form></div><div class="panel"><span class="eyebrow">PLAN WITH PERSPECTIVE</span><h3>Mortgage estimate</h3><form data-calculator data-price="<?= e($p['price_minor']/100) ?>"><label class="field"><span>Home price ($)</span><input type="number" name="price" value="<?= e($p['price_minor']/100) ?>" min="1"></label><label class="field"><span>Deposit ($)</span><input type="number" name="deposit" value="<?= e($p['price_minor']/500) ?>" min="0"></label><div class="form-grid"><label class="field"><span>Interest rate (%)</span><input type="number" name="rate" value="6.5" min="0" max="30" step=".1"></label><label class="field"><span>Term (years)</span><input type="number" name="years" value="30" min="1" max="50"></label><label class="field"><span>Annual taxes ($)</span><input type="number" name="taxes" value="0" min="0"></label><label class="field"><span>Annual insurance ($)</span><input type="number" name="insurance" value="0" min="0"></label></div><div class="calculator-output" aria-live="polite"><span data-payment></span><small> / month</small></div><p class="tiny">Estimate only. Assumptions are editable; excludes fees and mortgage insurance. No lender or rate feed is connected.</p></form></div></aside></div>
